-- Powder 21.0.2 · Hotfix Safety & Incident Response
begin;
create table if not exists public.hotfix_guardrails_v21002(
 channel text primary key check(channel in ('production','staging')),build_id text not null default 'powder-21.0.2-hotfix-safety',manifest_hash text not null default '',artifact_sha256 text not null default '',rollback_target_build text not null default 'powder-21.0.1-launch-stabilization',armed boolean not null default false,max_changed_files integer not null default 24,max_migrations integer not null default 2,state text not null default 'hold' check(state in ('ready','hold')),last_reason text not null default '',updated_at timestamptz not null default now(),updated_by text not null default '');
insert into public.hotfix_guardrails_v21002(channel) values('production'),('staging') on conflict(channel) do nothing;
create table if not exists public.hotfix_evidence_v21002(
 id bigint generated by default as identity primary key,channel text not null,build_id text not null,patch_id text not null,manifest_hash text not null,artifact_sha256 text not null,changed_file_count integer not null,migration_count integer not null,gameplay_critical_changes integer not null default 0,api_contract_changes integer not null default 0,destructive_schema_changes integer not null default 0,tests_pass boolean not null default false,rollback_ready boolean not null default false,rollback_target_build text not null,critical_open integer not null default 0,high_open integer not null default 0,status text not null check(status in ('pass','hold')),reasons jsonb not null default '[]'::jsonb,evidence_sha256 text not null,runner_revision text not null default '',checked_at timestamptz not null default now(),checked_by text not null default 'ci');
create index if not exists hotfix_evidence_v21002_latest_idx on public.hotfix_evidence_v21002(channel,build_id,checked_at desc);
create table if not exists public.hotfix_incidents_v21002(id bigint generated by default as identity primary key,channel text not null,build_id text not null,severity text not null check(severity in ('critical','high','medium','low')),category text not null,status text not null default 'open' check(status in ('open','monitoring','resolved')),summary text not null,evidence jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),created_by text not null default 'system',resolved_at timestamptz,resolved_by text not null default '');
alter table public.hotfix_guardrails_v21002 enable row level security;alter table public.hotfix_evidence_v21002 enable row level security;alter table public.hotfix_incidents_v21002 enable row level security;
revoke all on public.hotfix_guardrails_v21002,public.hotfix_evidence_v21002,public.hotfix_incidents_v21002 from public,anon,authenticated;grant select,insert,update on public.hotfix_guardrails_v21002,public.hotfix_evidence_v21002,public.hotfix_incidents_v21002 to service_role;grant usage,select on all sequences in schema public to service_role;
create or replace function public.powder_hotfix_record_evidence_v21002(p_channel text,p_build text,p_patch_id text,p_manifest_hash text,p_artifact_sha256 text,p_changed_file_count integer,p_migration_count integer,p_gameplay_critical_changes integer,p_api_contract_changes integer,p_destructive_schema_changes integer,p_tests_pass boolean,p_rollback_ready boolean,p_rollback_target_build text,p_critical_open integer,p_high_open integer,p_evidence_sha256 text,p_runner_revision text,p_actor text default 'ci') returns jsonb language plpgsql security definer set search_path=public as $f$
declare c text:=case when p_channel='staging' then 'staging' else 'production' end;cfg public.hotfix_guardrails_v21002;rs jsonb:='[]'::jsonb;st text:='pass';
begin if p_build<>'powder-21.0.2-hotfix-safety' then raise exception 'HF21002_BUILD_MISMATCH';end if;if p_manifest_hash !~ '^[0-9a-fA-F]{16,64}$' or p_artifact_sha256 !~ '^[0-9a-fA-F]{64}$' or p_evidence_sha256 !~ '^[0-9a-fA-F]{64}$' then raise exception 'HF21002_HASH_INVALID';end if;select * into cfg from public.hotfix_guardrails_v21002 where channel=c for update;if cfg.manifest_hash<>'' and lower(cfg.manifest_hash)<>lower(p_manifest_hash) then raise exception 'HF21002_MANIFEST_DRIFT';end if;if cfg.artifact_sha256<>'' and lower(cfg.artifact_sha256)<>lower(p_artifact_sha256) then raise exception 'HF21002_ARTIFACT_DRIFT';end if;
if p_changed_file_count<0 or p_changed_file_count>cfg.max_changed_files then st:='hold';rs:=rs||jsonb_build_array('changed_file_budget');end if;if p_migration_count<0 or p_migration_count>cfg.max_migrations then st:='hold';rs:=rs||jsonb_build_array('migration_budget');end if;if p_gameplay_critical_changes<>0 then st:='hold';rs:=rs||jsonb_build_array('gameplay_critical_change');end if;if p_api_contract_changes<>0 then st:='hold';rs:=rs||jsonb_build_array('api_contract_change');end if;if p_destructive_schema_changes<>0 then st:='hold';rs:=rs||jsonb_build_array('destructive_schema');end if;if not p_tests_pass then st:='hold';rs:=rs||jsonb_build_array('tests');end if;if not p_rollback_ready or coalesce(p_rollback_target_build,'')='' then st:='hold';rs:=rs||jsonb_build_array('rollback');end if;if p_critical_open>0 then st:='hold';rs:=rs||jsonb_build_array('critical_incident');end if;if p_high_open>0 then st:='hold';rs:=rs||jsonb_build_array('high_incident');end if;
insert into public.hotfix_evidence_v21002(channel,build_id,patch_id,manifest_hash,artifact_sha256,changed_file_count,migration_count,gameplay_critical_changes,api_contract_changes,destructive_schema_changes,tests_pass,rollback_ready,rollback_target_build,critical_open,high_open,status,reasons,evidence_sha256,runner_revision,checked_by) values(c,p_build,left(p_patch_id,120),lower(p_manifest_hash),lower(p_artifact_sha256),p_changed_file_count,p_migration_count,p_gameplay_critical_changes,p_api_contract_changes,p_destructive_schema_changes,p_tests_pass,p_rollback_ready,p_rollback_target_build,p_critical_open,p_high_open,st,rs,lower(p_evidence_sha256),left(coalesce(p_runner_revision,''),120),left(coalesce(p_actor,'ci'),160));
update public.hotfix_guardrails_v21002 set state=case when st='pass' then 'ready' else 'hold' end,last_reason=case when st='pass' then '' else rs::text end,updated_at=now(),updated_by=left(coalesce(p_actor,'ci'),160) where channel=c;if cfg.armed and st='hold' then update public.release_rollout_v1950 set emergency_mode='halt',emergency_message='Hotfix Safety 21.0.2 HOLD: '||rs::text,updated_at=now(),updated_by='hotfix-v21002' where channel=c;insert into public.hotfix_incidents_v21002(channel,build_id,severity,category,summary,evidence,created_by) values(c,p_build,case when p_gameplay_critical_changes>0 or p_destructive_schema_changes>0 then 'critical' else 'high' end,'hotfix_guard','Hotfix evidence exceeded safe patch budget',jsonb_build_object('reasons',rs,'patchId',p_patch_id),'hotfix-v21002');end if;return jsonb_build_object('ok',true,'status',st,'reasons',rs);end $f$;
create or replace function public.powder_hotfix_posture_v21002(p_channel text default 'production',p_build text default 'powder-21.0.2-hotfix-safety') returns jsonb language plpgsql security definer set search_path=public as $f$ declare c text:=case when p_channel='staging' then 'staging' else 'production' end;cfg public.hotfix_guardrails_v21002;ev public.hotfix_evidence_v21002;crit int:=0;hi int:=0;begin select * into cfg from public.hotfix_guardrails_v21002 where channel=c;select * into ev from public.hotfix_evidence_v21002 where channel=c and build_id=p_build order by checked_at desc limit 1;select count(*) filter(where severity='critical'),count(*) filter(where severity='high') into crit,hi from public.hotfix_incidents_v21002 where channel=c and build_id=p_build and status<>'resolved';return jsonb_build_object('ready',cfg.armed and ev.id is not null and ev.status='pass' and crit=0 and hi=0,'armed',coalesce(cfg.armed,false),'state',coalesce(cfg.state,'hold'),'openCritical',crit,'openHigh',hi,'rollbackReady',coalesce(ev.rollback_ready,false),'rollbackTargetBuild',coalesce(cfg.rollback_target_build,''),'latestCheckedAt',ev.checked_at);end $f$;
create or replace function public.powder_hotfix_arm_v21002(p_channel text,p_build text,p_manifest_hash text,p_artifact_sha256 text,p_rollback_target text,p_actor text) returns jsonb language plpgsql security definer set search_path=public as $f$ declare c text:=case when p_channel='staging' then 'staging' else 'production' end;begin if p_build<>'powder-21.0.2-hotfix-safety' or p_manifest_hash !~ '^[0-9a-fA-F]{16,64}$' or p_artifact_sha256 !~ '^[0-9a-fA-F]{64}$' then raise exception 'HF21002_ARM_INVALID';end if;if coalesce(p_rollback_target,'')='' or p_rollback_target=p_build then raise exception 'HF21002_ROLLBACK_INVALID';end if;update public.hotfix_guardrails_v21002 set build_id=p_build,manifest_hash=lower(p_manifest_hash),artifact_sha256=lower(p_artifact_sha256),rollback_target_build=p_rollback_target,armed=true,state='hold',last_reason='Awaiting CI hotfix evidence',updated_at=now(),updated_by=p_actor where channel=c;return public.powder_hotfix_posture_v21002(c,p_build);end $f$;
insert into public.security_admin_surfaces_v20160(function_name,allowed_roles,notes) values('powder-admin-hotfix-safety',array['owner','admin','support'],'21.0.2 hotfix posture; mutations Owner+AAL2.') on conflict(function_name) do update set allowed_roles=excluded.allowed_roles,notes=excluded.notes,updated_at=now();insert into public.security_critical_actions_v20160(function_name,action,require_owner,require_aal2) values('powder-admin-hotfix-safety','arm',true,true),('powder-admin-hotfix-safety','emergency_hold',true,true) on conflict(function_name,action) do update set require_owner=excluded.require_owner,require_aal2=excluded.require_aal2;
revoke all on function public.powder_hotfix_record_evidence_v21002(text,text,text,text,text,integer,integer,integer,integer,integer,boolean,boolean,text,integer,integer,text,text,text) from public,anon,authenticated;revoke all on function public.powder_hotfix_posture_v21002(text,text) from public,anon,authenticated;revoke all on function public.powder_hotfix_arm_v21002(text,text,text,text,text,text) from public,anon,authenticated;grant execute on function public.powder_hotfix_record_evidence_v21002(text,text,text,text,text,integer,integer,integer,integer,integer,boolean,boolean,text,integer,integer,text,text,text) to service_role;grant execute on function public.powder_hotfix_posture_v21002(text,text) to service_role;grant execute on function public.powder_hotfix_arm_v21002(text,text,text,text,text,text) to service_role;commit;
